const j = $json || {};
const jobId = (j.jobId || "").trim();
const assetKey = (j.assetKey || "").trim();
const assetType = (j.assetType || "infographic").trim();
const title = (j.title || "").trim();
const template = (j.template || "").trim();
const data = j.data || {};

const validTemplates = [
  "stats-grid", "process-steps", "comparison", "timeline",
  "checklist", "cost-breakdown", "before-after-explanation", "faq-summary"
];

if (!jobId) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "jobId is required for infographic renderer." };
}
if (!assetKey) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "assetKey is required for infographic renderer." };
}
if (!assetType) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "assetType is required for infographic renderer." };
}
if (!title) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "title is required for infographic renderer." };
}
if (!template || !validTemplates.includes(template)) {
  return { ok: false, errorCode: "INVALID_TEMPLATE", errorMessage: "template must be one of: " + validTemplates.join(", ") };
}
if (!data || typeof data !== "object") {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "data object is required for infographic template: " + template };
}

// Strict schema validation per template — NO fabricated fallbacks!
if (template === "stats-grid" && (!Array.isArray(data.stats) || data.stats.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template stats-grid requires a non-empty data.stats array." };
}
if (template === "process-steps" && (!Array.isArray(data.steps) || data.steps.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template process-steps requires a non-empty data.steps array." };
}
if (template === "comparison" && (!Array.isArray(data.items) || data.items.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template comparison requires a non-empty data.items array." };
}
if (template === "timeline" && (!Array.isArray(data.events) || data.events.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template timeline requires a non-empty data.events array." };
}
if (template === "checklist" && (!Array.isArray(data.list) || data.list.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template checklist requires a non-empty data.list array." };
}
if (template === "cost-breakdown" && (!Array.isArray(data.costs) || data.costs.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template cost-breakdown requires a non-empty data.costs array." };
}
if (template === "before-after-explanation" && (!Array.isArray(data.points) || data.points.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template before-after-explanation requires a non-empty data.points array." };
}
if (template === "faq-summary" && (!Array.isArray(data.faqs) || data.faqs.length === 0)) {
  return { ok: false, errorCode: "MISSING_TEMPLATE_DATA", errorMessage: "template faq-summary requires a non-empty data.faqs array." };
}

return {
  jobId,
  assetKey,
  assetType,
  language: j.language || "ar",
  template,
  title,
  data,
  ok: true
};

const p = $("02 Validate Infographic Input").item.json;

function escapeXml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

const title = escapeXml(p.title);
const template = p.template;
const data = p.data || {};
const isRtl = /[\u0600-\u06FF]/.test(title);
const width = 1080;
const height = 1080;
let innerSvg = "";

const textDir = isRtl ? 'direction="rtl" text-anchor="end"' : 'text-anchor="start"';
const titleX = isRtl ? 1020 : 60;

if (template === "stats-grid") {
  innerSvg = data.stats.slice(0, 4).map((s, idx) => {
    const col = idx % 2;
    const row = Math.floor(idx / 2);
    const x = 80 + col * 470;
    const y = 200 + row * 380;
    return `<g transform="translate(${x}, ${y})">
      <rect width="430" height="340" fill="#1e293b" rx="16" stroke="#38bdf8" stroke-width="2"/>
      <text x="215" y="150" fill="#38bdf8" font-family="sans-serif" font-size="64" font-weight="bold" text-anchor="middle">${escapeXml(s.value)}</text>
      <text x="215" y="230" fill="#cbd5e1" font-family="sans-serif" font-size="28" text-anchor="middle">${escapeXml(s.label)}</text>
    </g>`;
  }).join("");
} else if (template === "process-steps") {
  innerSvg = data.steps.slice(0, 4).map((step, idx) => {
    const y = 200 + idx * 190;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="150" fill="#1e293b" rx="12" stroke="#6366f1" stroke-width="2"/>
      <circle cx="80" cy="75" r="40" fill="#6366f1"/>
      <text x="80" y="85" fill="#ffffff" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">${idx + 1}</text>
      <text x="160" y="87" fill="#f8fafc" font-family="sans-serif" font-size="28">${escapeXml(step)}</text>
    </g>`;
  }).join("");
} else if (template === "comparison") {
  innerSvg = `<rect x="80" y="200" width="920" height="780" fill="#1e293b" rx="16" stroke="#334155" stroke-width="2"/>
  <line x1="540" y1="200" x2="540" y2="980" stroke="#334155" stroke-width="2"/>
  <text x="310" y="260" fill="#38bdf8" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">الخيار الأول</text>
  <text x="770" y="260" fill="#94a3b8" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="middle">الخيار الثاني</text>
  ` + data.items.slice(0, 5).map((it, idx) => {
    const y = 350 + idx * 120;
    return `<text x="310" y="${y}" fill="#ffffff" font-family="sans-serif" font-size="26" text-anchor="middle">${escapeXml(it.optionA || it.feature)}</text>
    <text x="770" y="${y}" fill="#cbd5e1" font-family="sans-serif" font-size="26" text-anchor="middle">${escapeXml(it.optionB || "-")}</text>`;
  }).join("");
} else if (template === "timeline") {
  innerSvg = data.events.slice(0, 4).map((ev, idx) => {
    const y = 200 + idx * 190;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="150" fill="#0f172a" rx="12" stroke="#0284c7" stroke-width="2"/>
      <text x="40" y="85" fill="#38bdf8" font-family="sans-serif" font-size="28" font-weight="bold">${escapeXml(ev.time)}</text>
      <text x="280" y="85" fill="#ffffff" font-family="sans-serif" font-size="28">${escapeXml(ev.title)}</text>
    </g>`;
  }).join("");
} else if (template === "checklist") {
  innerSvg = data.list.slice(0, 5).map((item, idx) => {
    const y = 200 + idx * 150;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="120" fill="#1e293b" rx="10" stroke="#10b981" stroke-width="2"/>
      <text x="40" y="72" fill="#10b981" font-family="sans-serif" font-size="36" font-weight="bold">✓</text>
      <text x="110" y="70" fill="#f8fafc" font-family="sans-serif" font-size="26">${escapeXml(item)}</text>
    </g>`;
  }).join("");
} else if (template === "cost-breakdown") {
  innerSvg = data.costs.slice(0, 4).map((c, idx) => {
    const y = 200 + idx * 190;
    const name = escapeXml(c.item || c.label || "بند التكلفة");
    const price = escapeXml(c.cost || c.price || "$0");
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="150" fill="#1e293b" rx="12" stroke="#f59e0b" stroke-width="2"/>
      <text x="50" y="85" fill="#ffffff" font-family="sans-serif" font-size="28">${name}</text>
      <text x="870" y="85" fill="#f59e0b" font-family="sans-serif" font-size="32" font-weight="bold" text-anchor="end">${price}</text>
    </g>`;
  }).join("");
} else if (template === "before-after-explanation") {
  innerSvg = `<rect x="80" y="200" width="920" height="360" fill="#1e293b" rx="16" stroke="#ec4899" stroke-width="2"/>
  <text x="540" y="390" fill="#ec4899" font-family="sans-serif" font-size="36" font-weight="bold" text-anchor="middle">توضيح النتائج قبل وبعد</text>
  ` + data.points.slice(0, 3).map((pt, idx) => {
    const y = 600 + idx * 120;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="100" fill="#0f172a" rx="8" stroke="#334155" stroke-width="1"/>
      <text x="40" y="60" fill="#cbd5e1" font-family="sans-serif" font-size="24">• ${escapeXml(pt)}</text>
    </g>`;
  }).join("");
} else {
  innerSvg = data.faqs.slice(0, 3).map((faq, idx) => {
    const y = 200 + idx * 250;
    return `<g transform="translate(80, ${y})">
      <rect width="920" height="210" fill="#1e293b" rx="14" stroke="#8b5cf6" stroke-width="2"/>
      <text x="40" y="75" fill="#c084fc" font-family="sans-serif" font-size="28" font-weight="bold">س: ${escapeXml(faq.question)}</text>
      <text x="40" y="145" fill="#ffffff" font-family="sans-serif" font-size="24">ج: ${escapeXml(faq.answer)}</text>
    </g>`;
  }).join("");
}

const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="#0f172a"/>
  <rect x="30" y="30" width="1020" height="1020" fill="none" stroke="#38bdf8" stroke-width="4" rx="24"/>
  <text x="${titleX}" y="120" fill="#38bdf8" font-family="sans-serif" font-size="38" font-weight="bold" ${textDir}>${title}</text>
  ${innerSvg}
</svg>`;

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: p.assetKey,
    assetType: p.assetType,
    language: p.language,
    template: p.template,
    width,
    height,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    checksum: "",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: `${p.assetKey}.svg`,
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    json: {
      success: false,
      jobId: meta.jobId || null,
      assetKey: meta.assetKey || null,
      assetType: meta.assetType || null,
      status: "FAILED",
      message: "Infographic rendering failed — no binary image output produced.",
      data: null,
      warnings: [],
      errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Infographic renderer did not produce binary output data." }],
      nextAllowedActions: ["retry", "cancel"]
    },
    binary: item.binary
  };
}

const norm = {
  success: true,
  jobId: meta.jobId,
  status: "ASSET_GENERATED",
  message: "Infographic rendered successfully using template: " + meta.template,
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    template: meta.template,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

return {
  json: {
    jobId: meta.jobId,
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    language: meta.language,
    template: meta.template,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    checksum: meta.checksum,
    mimeType: meta.mimeType,
    normalized: norm
  },
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "INVALID_TEMPLATE";
const message = j.errorMessage || "Invalid infographic template selection or input data.";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    assetKey: j.assetKey || null,
    assetType: j.assetType || null,
    status: "FAILED",
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
